import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BTjPRYTP.js";const p=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md"}'),o={name:"features/dashboard.md"};function i(d,e,n,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The TeslaSync dashboard is the central hub for monitoring your entire Tesla fleet at a glance. It provides real-time statistics, live vehicle states, and key metrics — all rendered with a modern glassmorphism UI.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>When you open TeslaSync, the Dashboard is the first page you see. It displays:</p><ul><li><strong>Fleet summary cards</strong> — Total vehicles, active drives, charging sessions, and alerts</li><li><strong>Live vehicle status</strong> — Each vehicle&#39;s current state (online, asleep, driving, charging)</li><li><strong>Key metrics</strong> — Battery levels, total mileage, energy consumed, estimated costs</li><li><strong>Recent activity</strong> — Latest drives, charging sessions, and alerts</li></ul><h2 id="fleet-summary-cards" tabindex="-1">Fleet Summary Cards <a class="header-anchor" href="#fleet-summary-cards" aria-label="Permalink to &quot;Fleet Summary Cards&quot;">​</a></h2><p>At the top of the dashboard, stat cards provide a quick snapshot:</p><table tabindex="0"><thead><tr><th>Card</th><th>Description</th></tr></thead><tbody><tr><td><strong>Vehicles</strong></td><td>Total number of tracked vehicles and how many are currently online</td></tr><tr><td><strong>Active Drives</strong></td><td>Number of vehicles currently driving, with total distance today</td></tr><tr><td><strong>Charging</strong></td><td>Vehicles currently charging, with energy being added</td></tr><tr><td><strong>Alerts</strong></td><td>Unread alerts count with severity breakdown</td></tr></tbody></table><p>Each card uses the <code>StatCard</code> glass component with animated counters.</p><h2 id="vehicle-status-grid" tabindex="-1">Vehicle Status Grid <a class="header-anchor" href="#vehicle-status-grid" aria-label="Permalink to &quot;Vehicle Status Grid&quot;">​</a></h2><p>Below the summary cards, each vehicle is displayed as a card showing:</p><ul><li><strong>Display name</strong> and model (e.g., &quot;My Model 3 — Long Range&quot;)</li><li><strong>Current state</strong> — Online (green), Asleep (gray), Driving (blue), Charging (amber)</li><li><strong>Battery level</strong> — Visual gauge with percentage</li><li><strong>Rated range</strong> — Estimated range in km or miles (based on settings)</li><li><strong>Location</strong> — Last known address or GPS coordinates</li><li><strong>Temperature</strong> — Inside and outside temps</li></ul><p>Click any vehicle card to navigate to the <a href="/teslasync/features/vehicle-tracking.html">Vehicle Detail</a> page.</p><h2 id="real-time-updates" tabindex="-1">Real-Time Updates <a class="header-anchor" href="#real-time-updates" aria-label="Permalink to &quot;Real-Time Updates&quot;">​</a></h2><p>The dashboard uses <strong>Server-Sent Events (SSE)</strong> to receive live updates without polling:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ←── SSE ←── Backend ←── Tesla API (polled every 15s)</span></span></code></pre></div><p>When the worker polls new vehicle data, it broadcasts events to all connected dashboard clients. You&#39;ll see:</p><ul><li>Battery levels update in real time</li><li>Vehicle states change as cars wake, sleep, drive, or charge</li><li>New alerts appear immediately</li><li>Charging progress updates live</li></ul><p>The connection indicator in the top-right shows whether the SSE connection is active (green dot) or disconnected (red dot). Auto-reconnect happens within 3 seconds.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>The dashboard supports 5 visual themes, selectable from Settings or the theme picker:</p><table tabindex="0"><thead><tr><th>Theme</th><th>Primary Color</th><th>Style</th></tr></thead><tbody><tr><td><strong>Neon Cyan</strong></td><td><code>#00f0ff</code></td><td>Default — electric blue/cyan glassmorphism</td></tr><tr><td><strong>Tesla Red</strong></td><td><code>#e82127</code></td><td>Tesla brand red</td></tr><tr><td><strong>Matrix Green</strong></td><td><code>#00ff41</code></td><td>Hacker/matrix green</td></tr><tr><td><strong>Royal Purple</strong></td><td><code>#7c3aed</code></td><td>Deep purple elegance</td></tr><tr><td><strong>Solar Amber</strong></td><td><code>#f59e0b</code></td><td>Warm amber/gold</td></tr></tbody></table><p>Themes are applied via CSS custom properties and stored in localStorage for persistence.</p><h2 id="command-palette" tabindex="-1">Command Palette <a class="header-anchor" href="#command-palette" aria-label="Permalink to &quot;Command Palette&quot;">​</a></h2><p>Press <strong>Cmd+K</strong> (Mac) or <strong>Ctrl+K</strong> (Windows/Linux) to open the command palette. This provides instant navigation to any page or vehicle:</p><ul><li>Type &quot;Model 3&quot; to jump to that vehicle&#39;s detail page</li><li>Type &quot;charging&quot; to open the charging history page</li><li>Type &quot;settings&quot; to go to application settings</li></ul><p>The command palette searches across page names, vehicle names, and VINs.</p><h2 id="responsive-design" tabindex="-1">Responsive Design <a class="header-anchor" href="#responsive-design" aria-label="Permalink to &quot;Responsive Design&quot;">​</a></h2><p>The dashboard is fully responsive:</p><ul><li><strong>Desktop</strong> (1280px+): 4-column grid for stat cards, 3-column vehicle grid</li><li><strong>Tablet</strong> (768–1279px): 2-column grid layout</li><li><strong>Mobile</strong> (&lt; 768px): Single-column stacked layout with collapsible sidebar</li></ul><h2 id="api-endpoints-used" tabindex="-1">API Endpoints Used <a class="header-anchor" href="#api-endpoints-used" aria-label="Permalink to &quot;API Endpoints Used&quot;">​</a></h2><p>The dashboard fetches data from these backend endpoints:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/api/v1/vehicles</code></td><td>GET</td><td>List all vehicles with current state</td></tr><tr><td><code>/api/v1/events</code></td><td>GET (SSE)</td><td>Real-time event stream</td></tr><tr><td><code>/api/v1/alerts</code></td><td>GET</td><td>Unread alerts count</td></tr><tr><td><code>/api/v1/analytics/fleet</code></td><td>GET</td><td>Fleet-wide summary statistics</td></tr></tbody></table><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><p>The dashboard is composed of reusable widget components from <code>Widgets.tsx</code>:</p><ul><li><strong>BatteryGauge</strong> — Circular progress indicator for battery level</li><li><strong>RangeBar</strong> — Horizontal bar showing rated vs. ideal range</li><li><strong>SpeedIndicator</strong> — Current speed display (0 when parked)</li><li><strong>TempDisplay</strong> — Inside/outside temperature with icons</li><li><strong>AlertBadge</strong> — Badge showing unread alert count by severity</li></ul>',36)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
